// Map folder IDs to folder names manually (replace with your folder IDs)
const folderMapping = {
  '1hicgOLjO...DrWT': 'Food',
  '1jXusDvhg...Ve7pFB5': 'People',
  '1PQtcJ-Fs...P4cM': 'Shopfront'
};

const requiredFolders = ['Food', 'People', 'Shopfront'];
const minFiles = 5;

const filesGrouped = {};

// Group files based on parent folder
$input.all().forEach(item => {
  const parentId = item.json.parents ? item.json.parents[0] : null;
  const folderName = folderMapping[parentId] || 'Unknown';

  if (!filesGrouped[folderName]) {
    filesGrouped[folderName] = [];
  }
  filesGrouped[folderName].push(item.json);
});

// Check file count per folder
const foldersWithLowFiles = requiredFolders.filter(folder => {
  return !filesGrouped[folder] || filesGrouped[folder].length < minFiles;
});

return [
  {
    json: {
      validation_passed: foldersWithLowFiles.length === 0,
      folders_with_low_files: foldersWithLowFiles,
      files_grouped: filesGrouped
    }
  }
];

const filesGrouped = $json.files_grouped; 
const rotationHistory = $json.rotation_history || {}; // (In future, store externally - e.g., DB or GHL custom values)

const selectedContent = [];
const maxPosts = 3; // Example: 3 posts (1 per folder); adjust as needed

Object.keys(filesGrouped).forEach(folder => {
  const unusedFiles = filesGrouped[folder].filter(file => {
    const lastUsed = rotationHistory[file.id];
    if (!lastUsed) return true;

    const thirtyDays = 30 * 24 * 60 * 60 * 1000;
    return Date.now() - lastUsed > thirtyDays;
  });

  if (unusedFiles.length > 0) {
    // ✅ Randomly pick 1 unused file per folder
    const randomFile = unusedFiles[Math.floor(Math.random() * unusedFiles.length)];

    selectedContent.push({
      folder,
      file: {
        id: randomFile.id,
        name: randomFile.name,
        url: randomFile.webContentLink || `https://drive.google.com/uc?id=${randomFile.id}`
      }
    });

    // ✅ Update rotation history (later save externally)
    rotationHistory[randomFile.id] = Date.now();
  }
});

// ✅ Limit total posts (e.g., only 1 if needed)
return [
  {
    json: {
      selected_content: selectedContent.slice(0, maxPosts),
      rotation_history: rotationHistory // Keep history for next run
    }
  }
];

// Required folders for validation
const requiredFolders = ['Food', 'People', 'Shopfront'];

// Extract all folder names from the Google Drive output
const allFolders = $input.all().map(item => item.json.name);

// Identify missing folders
const missingFolders = requiredFolders.filter(folder => !allFolders.includes(folder));

return [
  {
    json: {
      validation_passed: missingFolders.length === 0,
      missing_folders: missingFolders,
      all_folders: allFolders
    }
  }
];

